import { useCallback, useEffect, useMemo, useRef } from 'react';

import {
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  useSubFilters,
} from 'hooks';
import type { FilterForm, Option } from 'models/Filters';

import { CR_WATERFALL_RESET_EVENT } from '../../constants';
import {
  buildPostAppliedForDrill,
  getAvailableWaterfallOptions,
  getNextWaterfallFilterAfterDrill,
  hasSpecificValue,
  resolveWaterfallFilterForAppliedState,
  shouldLockWaterfallToSku,
} from '../../utils/resolveCommercialResultsWaterfallOptions';

interface AppliedChanges {
  brandsChanged: boolean;
  subBrandsChanged: boolean;
  regionChanged: boolean;
  channelChanged: boolean;
  packTypeChanged: boolean;
  skuChanged: boolean;
  periodsChanged: boolean;
}

const detectAppliedChanges = (
  prev: FilterForm | undefined,
  next: FilterForm | undefined,
): AppliedChanges => ({
  brandsChanged: prev?.brands !== next?.brands,
  subBrandsChanged: prev?.sub_brands !== next?.sub_brands,
  regionChanged: prev?.region !== next?.region,
  channelChanged: prev?.channel !== next?.channel,
  packTypeChanged: prev?.pack_type !== next?.pack_type,
  skuChanged: prev?.sku !== next?.sku,
  periodsChanged: prev?.periods !== next?.periods,
});

interface UseCommercialResultsWaterfallFilterSyncParams {
  contextKey: string;
  rawOptions: Option[];
}

export const useCommercialResultsWaterfallFilterSync = ({
  rawOptions,
}: UseCommercialResultsWaterfallFilterSyncParams) => {
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);
  const { activeSubFilters, setSubFilterValue } = useSubFilters();
  const { applyDirect } = usePageFilterManagement(currentPage);

  const availableOptions = useMemo(
    () => getAvailableWaterfallOptions(applied, dataFilters, rawOptions),
    [applied, dataFilters, rawOptions],
  );

  const currentWaterfallFilter = activeSubFilters?.waterfall_filter as
    string | undefined;

  const currentWaterfallFilterRef = useRef(currentWaterfallFilter);
  currentWaterfallFilterRef.current = currentWaterfallFilter;

  const availableOptionsRef = useRef(availableOptions);
  availableOptionsRef.current = availableOptions;

  const handleWaterfallFilterChange = useCallback(
    (value: string) => {
      if (hasSpecificValue(applied?.sku)) {
        applyDirect({
          sku: 'All',
        });
      }
      setSubFilterValue('waterfall_filter', value);
    },
    [setSubFilterValue, applied, applyDirect],
  );

  const syncWaterfallFilterAfterDrill = useCallback(
    (
      currentView: string,
      clickedLabel: string | string[],
      nextRawOptions: Option[] = rawOptions,
    ) => {
      if (currentView === 'sku') {
        return;
      }
      const postApplied = buildPostAppliedForDrill(
        applied,
        currentView,
        clickedLabel,
      );
      const nextFilter = getNextWaterfallFilterAfterDrill(
        currentView,
        postApplied,
        dataFilters,
        nextRawOptions,
        applied,
      );

      if (nextFilter) {
        setSubFilterValue('waterfall_filter', nextFilter);
      }
    },
    [applied, dataFilters, rawOptions, setSubFilterValue],
  );

  const resolveValueOnContextChange = useCallback(
    ({
      availableOptions: opts,
    }: {
      currentValue: string;
      availableOptions: Option[];
      defaultOption: unknown;
      contextKey: string;
    }) => {
      return resolveWaterfallFilterForAppliedState(applied, opts, dataFilters);
    },
    [dataFilters, applied],
  );

  useEffect(() => {
    const handleFilterReset = () => {
      const next = resolveWaterfallFilterForAppliedState(
        applied,
        availableOptionsRef.current,
        dataFilters,
      );
      if (next && next !== currentWaterfallFilterRef.current) {
        setSubFilterValue('waterfall_filter', next);
      }
    };
    globalThis.addEventListener(CR_WATERFALL_RESET_EVENT, handleFilterReset);
    return () =>
      globalThis.removeEventListener(
        CR_WATERFALL_RESET_EVENT,
        handleFilterReset,
      );
  }, [setSubFilterValue, dataFilters, applied]);

  const prevAppliedRef = useRef<typeof applied | undefined>(undefined);

  useEffect(() => {
    const prev = prevAppliedRef.current;
    prevAppliedRef.current = applied;

    if (!currentWaterfallFilter) {
      return;
    }

    if (shouldLockWaterfallToSku(applied)) {
      if (currentWaterfallFilter !== 'sku') {
        setSubFilterValue('waterfall_filter', 'sku');
      }
      return;
    }

    if (!availableOptions.length) {
      return;
    }

    const nextValue = resolveWaterfallFilterForAppliedState(
      applied,
      availableOptions,
      dataFilters,
    );

    if (prev === undefined) {
      if (nextValue && nextValue !== currentWaterfallFilter) {
        setSubFilterValue('waterfall_filter', nextValue);
      }
      return;
    }

    const changes = detectAppliedChanges(prev, applied);
    const anyFilterChanged = Object.values(changes).some(Boolean);

    if (!anyFilterChanged) {
      return;
    }

    const currentViewStillAvailable = availableOptions.some(
      (option) => option.value === currentWaterfallFilter,
    );

    if (!currentViewStillAvailable && nextValue) {
      setSubFilterValue('waterfall_filter', nextValue);
    }
  }, [
    applied,
    currentWaterfallFilter,
    setSubFilterValue,
    availableOptions,
    dataFilters,
  ]);

  return {
    handleWaterfallFilterChange,
    syncWaterfallFilterAfterDrill,
    resolveValueOnContextChange,
    availableOptions,
  };
};
